oxy_webhelp_navlinks = {"tocId-d39307e6339":{"topics":[{"title":"High Availability for Rubrik clusters","shortdesc":"<p class=\"shortdesc\">High Availability keeps backup and archival operations running even when a Rubrik         cluster becomes unavailable. By pairing clusters into primary and secondary roles, you can         fail over to the secondary cluster and continue your scheduled backups and uploads with         minimal disruption.<\/p>","href":"hadr\/hadr_overview.html","attributes":{"data-id":"hadr_overview"},"menu":{"hasChildren":true},"tocID":"hadr_overview-d39307e6345","next":"hadr_overview-d39307e6345"}]}};